from fastapi import APIRouter, Depends, Query, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.core.deps import get_current_user
from app.crud.category_crud import category_crud
from app.database import get_db
from app.models import User
from app.schemas.category import CategoryCreate, CategoryOut, CategoryUpdate

router = APIRouter(prefix="/categories", tags=["Categories"])

# Every endpoint is scoped to the current user: other users' records are 404.


@router.post("/", response_model=CategoryOut, status_code=status.HTTP_201_CREATED)
async def create_category(
    item_in: CategoryCreate,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    return await category_crud.create(db, obj_in=item_in, user_id=current_user.id)


@router.get("/", response_model=list[CategoryOut])
async def list_categories(
    skip: int = Query(0, ge=0),
    limit: int = Query(20, ge=1, le=100),
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    return await category_crud.get_all(db, skip=skip, limit=limit, user_id=current_user.id)


@router.get("/{item_id}", response_model=CategoryOut)
async def get_category(
    item_id: int,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    return await category_crud.get(db, id=item_id, user_id=current_user.id)


@router.put("/{item_id}", response_model=CategoryOut)
async def replace_category(
    item_id: int,
    item_in: CategoryCreate,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """Full update: required fields must be sent."""
    item = await category_crud.get(db, id=item_id, user_id=current_user.id)
    return await category_crud.update(db, db_obj=item, obj_in=item_in.model_dump(exclude_unset=True))


@router.patch("/{item_id}", response_model=CategoryOut)
async def update_category(
    item_id: int,
    item_in: CategoryUpdate,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """Partial update: only the fields sent are changed."""
    item = await category_crud.get(db, id=item_id, user_id=current_user.id)
    return await category_crud.update(db, db_obj=item, obj_in=item_in)


@router.delete("/{item_id}")
async def delete_category(
    item_id: int,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    await category_crud.delete(db, id=item_id, user_id=current_user.id)
    return {"detail": "Category deleted successfully"}
